revoke all on function public.person_name_norm(text) from public, anon, authenticated, service_role;
grant execute on function public.person_name_norm(text) to authenticated, service_role;          -- the name trigger runs as the writer
revoke all on function public.person_name_problem(text) from public, anon, authenticated, service_role;
grant execute on function public.person_name_problem(text) to authenticated, service_role;
revoke all on function public.person_name_message(text, text) from public, anon, authenticated, service_role;
grant execute on function public.person_name_message(text, text) to authenticated, service_role;
revoke all on function public.person_name_key(text) from public, anon, authenticated, service_role;
grant execute on function public.person_name_key(text) to authenticated, service_role;
revoke all on function public.person_name_words(text) from public, anon, authenticated, service_role;
grant execute on function public.person_name_words(text) to authenticated, service_role;           -- the messages' suggestions (fifth version)
revoke all on function public.person_name_bracket_fix(text) from public, anon, authenticated, service_role;
grant execute on function public.person_name_bracket_fix(text) to authenticated, service_role;
revoke all on table private.name_skeleton from public, anon, authenticated, service_role;
grant select on table private.name_skeleton to authenticated, service_role;                      -- read by person_name_key as the writer

-- ── 2. existing names (the trigger profiles_clean_name of 0039_names_rule_2 is unchanged) ──
do $$
declare total int; renamed int; renamed_flagged int; rekeyed int; flagged_before int; flagged_after int; twins_before int; twins_after int;
begin
  select count(*), count(*) filter (where name_needs_fix) into total, flagged_before from public.profiles;
  select count(*) into twins_before from (select name_key from public.profiles group by name_key having count(*) > 1) t;
  -- allowed once normalised: stored normalised
  update public.profiles set name = public.person_name_norm(name)
   where name is distinct from public.person_name_norm(name) and public.person_name_problem(public.person_name_norm(name)) = '';
  get diagnostics renamed = row_count;
  -- breaks the rule for another reason: normalised too (its Arabic diacritics removed, invisible characters gone; normalising never
  -- removes any other mark, so it reads as it did) — a server write, which the trigger stores normalised and keeps flagged
  update public.profiles set name = public.person_name_norm(name)
   where name is distinct from public.person_name_norm(name) and public.person_name_norm(name) <> '';
  get diagnostics renamed_flagged = row_count;
  -- every row keyed and flagged by this rule (the trigger computes both when the key is cleared and the name kept)
  update public.profiles set name_key = null
   where name_key is distinct from public.person_name_key(name)
      or name_needs_fix is distinct from (public.person_name_problem(public.person_name_norm(name)) <> '');
  get diagnostics rekeyed = row_count;
  select count(*) filter (where name_needs_fix) into flagged_after from public.profiles;
  select count(*) into twins_after from (select name_key from public.profiles group by name_key having count(*) > 1) t;
  raise notice 'names (0039_names_rule_7): % profiles, % stored normalised (allowed), % names that break the rule normalised (still flagged), % rekeyed or reflagged, flagged % → %, skeletons shared by several members % → %',
    total, renamed, renamed_flagged, rekeyed, flagged_before, flagged_after, twins_before, twins_after;
end $$;

notify pgrst, 'reload schema';
